{
  "category_edits": [
    {
      "category": "embedding_representation",
      "rationale": "Untie history and candidate item embeddings in each category's single HSTU model, retaining width 64. Clone the initialized history table into a jointly trained candidate table to preserve initial scores while allowing context and target representations to specialize. Keep attention, frequency features, readout, dot-product scoring, loss and optimizer fixed.",
      "edits": [
        {
          "find": "DATA_DIR = os.environ.get(\"GAGC_DATA_DIR\", \"./input/trainval\")",
          "replace": "DATA_DIR = os.environ['GAGC_DATA_DIR']"
        },
        {
          "find": "            nn.init.xavier_uniform_(self.pos_emb.weight)\n            self.pos_emb.weight[0].zero_()",
          "replace": "            nn.init.xavier_uniform_(self.pos_emb.weight)\n            self.pos_emb.weight[0].zero_()\n        self.candidate_emb = nn.Embedding.from_pretrained(\n            self.item_emb.weight.detach().clone(), freeze=False, padding_idx=0\n        )"
        },
        {
          "find": "            scores = torch.matmul(model.item_emb(cand_t), user_emb)\n",
          "replace": "            scores = torch.matmul(model.candidate_emb(cand_t), user_emb)\n"
        },
        {
          "find": "            pos_scores = (out * model.item_emb(pos_t)).sum(dim=-1)\n            neg_scores = (out * model.item_emb(neg_t)).sum(dim=-1)",
          "replace": "            pos_scores = (out * model.candidate_emb(pos_t)).sum(dim=-1)\n            neg_scores = (out * model.candidate_emb(neg_t)).sum(dim=-1)"
        },
        {
          "find": "required_features = (\"input_log_frequency\", \"log_frequency_mean\", \"log_frequency_std\", \"frequency_projection.weight\")",
          "replace": "required_features = (\"input_log_frequency\", \"log_frequency_mean\", \"log_frequency_std\", \"frequency_projection.weight\", \"candidate_emb.weight\")"
        },
        {
          "find": "scores = torch.matmul(model.item_emb(cand_t), user_emb).cpu().tolist()",
          "replace": "scores = torch.matmul(model.candidate_emb(cand_t), user_emb).cpu().tolist()"
        }
      ]
    }
  ],
  "change_summary": "Separate history and candidate embeddings across all four category models. Both tables remain jointly trained and checkpointed within one HSTU model per category; validation and the generated predictor consistently use the candidate table."
}
